const AREAS = {
  city: 'City of London', southbank: 'Southbank', westminster: 'Westminster', bloomsbury: 'Bloomsbury',
  mayfair: "Mayfair e St James's", westend: 'West End', kensington: 'Kensington e Hyde Park', camden: "Camden e Regent's Park",
  greenwich: 'Greenwich', windsor: 'Windsor', kingscross: "King's Cross", fora: 'Além de Londres',
};
function ponto(id) { return (typeof DB !== 'undefined' && DB && Array.isArray(DB.pontos) && DB.pontos.find(p => p.id === id)) || PONTOS.find(p => p.id === id) || null; }

if (typeof module !== 'undefined') module.exports = { PONTOS, AREAS, ponto };
